RSpec.describe Timekeeping::EntryWriteClient, "caller-supplied Idempotency-Key" do
  let(:keyed_base_url) { "http://timekeeping.test" }
  let(:keyed_company) { create(:company) }
  let(:keyed_admin) { create(:user, current_workspace_id: keyed_company.id) }
  let(:keyed_project) { create(:project, billable: true, client: create(:client, company: keyed_company)) }
  let(:keyed_fake) { TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key) }

  around do |example|
    with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV, timekeeping_key_pair.to_pem) do
      with_timekeeping_env(Timekeeping::EntryApiClient::BASE_URL_ENV, keyed_base_url) { example.run }
    end
  end

  before do
    create(:employment, company: keyed_company, user: keyed_admin)
    keyed_admin.add_role :admin, keyed_company
    keyed_fake.register_company(id: keyed_company.id, edit_days: keyed_company.timesheet_edit_days)
    keyed_fake.register_user(id: keyed_admin.id, company_id: keyed_company.id, role: "admin")
    keyed_fake.register_project(id: keyed_project.id, company_id: keyed_company.id)
    route_timekeeping_to_fake(keyed_fake, base_url: keyed_base_url)
  end

  def keyed_context
    # Each import run builds its context with a fresh random request id.
    Timekeeping::WriteContext.new(company: keyed_company, actor: keyed_admin, actor_kind: "import",
                                  request_id: SecureRandom.uuid)
  end

  def keyed_body(note)
    {
      "project_id" => keyed_project.id, "user_id" => keyed_admin.id, "work_date" => Date.current.iso8601,
      "duration" => 30.0, "note" => note, "source" => "import", "source_metadata" => { "tool" => "harvest" }
    }
  end

  # "Forwarded writes use an `Idempotency-Key` built from the data import id and a digest of the row, so rerunning a failed import does not duplicate rows it already forwarded."
  it "a create resent under a new request id with the same given Idempotency-Key replays one entry, and a different key creates another" do
    row_one_key = Digest::UUID.uuid_v5(Digest::UUID::OID_NAMESPACE, "harvest-import/1/row-one")
    row_two_key = Digest::UUID.uuid_v5(Digest::UUID::OID_NAMESPACE, "harvest-import/1/row-two")
    client = described_class.new

    first = client.create_entry(context: keyed_context, generation: keyed_fake.generation,
                                body: keyed_body("row one"), idempotency_key: row_one_key)
    rerun = client.create_entry(context: keyed_context, generation: keyed_fake.generation,
                                body: keyed_body("row one"), idempotency_key: row_one_key)
    other = client.create_entry(context: keyed_context, generation: keyed_fake.generation,
                                body: keyed_body("row two"), idempotency_key: row_two_key)

    expect(rerun["id"]).to eq(first["id"])
    expect(other["id"]).not_to eq(first["id"])
    sent_keys = keyed_fake.requests.filter_map { |request| request[:headers]["Idempotency-Key"] if request[:method] == "POST" }
    expect(sent_keys).to eq([row_one_key, row_one_key, row_two_key])
  end
end

